---@field CommonBtnConsumePop           	Engine.Modules.LuaBehaviour             @ 显示 改名花费
---@field BtnCancel                     	UnityEngine.UI.Button                   @ 回退键
local Player2DRenamePanel = Class('Player2DRenamePanel')

-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Vector3 = CS.UnityEngine.Vector3

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

---@type Interfaces
local Interfaces = Interfaces
local gameUtils = GameUtils

-- ========================================================


function Player2DRenamePanel:__init()
    self.inputPlayerName = nil
    self.controller = nil
    self.co = nil   -- 发送携程请求
end


function Player2DRenamePanel:__delete()
    self.co = nil
end



function Player2DRenamePanel:Awake()
    KTool.SetActive(self.controller.gameObject, true);

    SetButtonAction(self.BtnCancel, Bind(self, self._OnClickBtnClose))
    SetButtonAction(self.BtnConfirm, Bind(self, self._OnClickBtnConfirm))

    -- 基础参数表:
    self.goodsId  = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 27).num
    self.goodNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 28).num

    -- 备用消耗资源:
    -- self.secondGoodsId  = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 40).num
    -- self.secondGoodNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 41).num

    ---@type CommonBtnConsumePop
    self.commonBtnConsumePop = CfUtils.GetLuaScr(self.CommonBtnConsumePop, "Game.UI.Common.CommonBtnConsumePop")
    self.commonBtnConsumePop:RefreshUI( self.goodsId, self.goodNum )


    self.InputField.enabled = true
    -- 用户按下 回车键 后:
    self.InputField.onEndEdit:AddListener(function()
        if string.len(self.InputField.text) > 0 then
            print("koko 想要的新名字: " .. tostring(self.InputField.text) )
        elseif string.len(self.InputField.text) == 0 then
            print(" koko 想要的新名字:  empty" )
        end
        self.inputPlayerName = self.InputField.text
    end)
end


function Player2DRenamePanel:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- =============================================================

function Player2DRenamePanel:_OnClickBtnClose()
    --print("koko - 按下 Btn Cancel")
    Object.Destroy( self.controller.gameObject )
end


function Player2DRenamePanel:_OnClickBtnConfirm()

    if isNull(self.inputPlayerName) or string.len(self.inputPlayerName) == 0 then 
        gameUtils.Toast(localize("用户名不能为空")) -- 飘字
        return
    end 

    -- 一级消耗道具:
    local firstConsumeNum = checkNumber(self.goodNum)       -- 道具 需要消耗数
    local firstCurNum = GoodsUtils.GetThingNo(self.goodsId) -- 道具 实际拥有数
    -- 二级消耗道具:
    -- local secondConsumeNum = checkNumber(self.secondGoodNum)       -- 道具 需要消耗数
    -- local secondCurNum = GoodsUtils.GetThingNo(self.secondGoodsId) -- 道具 实际拥有数

    ---
    if firstConsumeNum > firstCurNum then 
        -- 一级消耗道具不足:
        local orderInLayer = 1100 -- 确保弹窗 层级高于 本弹窗
        GoodsUtils.CheckConsumeDataCondition( { {goodsId = self.goodsId, num = self.goodNum } }, orderInLayer )
        self:_OnClickBtnClose() -- 主动关闭 本窗口
        return
    end 
    
    ---
    GameUtils.Request(Interfaces.PlayerChangePlayerName, { playerName = self.inputPlayerName}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            --checkin logical
            local data = checkTable(response.data)
            local playerName = data.playerName

            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if isNotNull(playerComponent) then
                playerComponent.playerDojo.playerName = playerName
            end

            Events.Broadcast(Constants.EventNames.Player2DMainRefreshLeftPanel, false) -- 重新绘制 个人信息界面2D 主界面 左侧面板

            -- 消耗道具 ... 
            GoodsUtils.ConsumeGoods({
                {
                    goodsId = self.goodsId,
                    num = self.goodNum
                }
            }, false)

            gameUtils.Toast(localize("改名成功")) -- 飘字
            self:_OnClickBtnClose() -- 主动关闭 本窗口
        end
    end)
end


return Player2DRenamePanel
